(n, d, h) = map(int, input().split())
if d > 2 * h or (h == 0 and n > 1) or (d == 1 and n > 2):
	print(-1)
else:
	fr = 2
	for i in range(h):
		print('{} {}'.format(fr - 1, fr))
		fr += 1
	if d == h:
		while fr <= n:
			print('2 {}'.format(fr))
			fr += 1
	else:
		(last, next) = (1, h + 2)
		for i in range(d - h):
			print('{} {}'.format(last, next))
			(last, next) = (next, next + 1)
		while next <= n:
			print('1 {}'.format(next))
			next += 1
